<?php
declare(strict_types=1); session_start(); require_once __DIR__.'/config.php';
$pdo=App\Database::getConnection(); $repo=new App\ProductRepository($pdo);
$category=filter_input(INPUT_GET,'category',FILTER_VALIDATE_INT); $search=trim((string)($_GET['search']??''));
if ($category && $category > 0) { $_SESSION['preferred_category_id'] = $category; }
$products=($category && $category>0)?$repo->findByCategory($category):(($search!=='')?$repo->findBySearch($search):$repo->findAll());
$categories=(new App\CategoryRepository($pdo))->findAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Browse listings · Bantayan Marketplace</title><link rel="stylesheet" href="assets/marketplace.css"></head><body><?php include __DIR__.'/includes/market-header.php'; ?><main class="wrap section"><div class="row"><h1>Fresh finds around the island</h1><span class="muted"><?= count($products) ?> listings</span></div><p class="muted"><?php if(!empty($_SESSION['user'])): ?>Signed in as <?= htmlspecialchars($_SESSION['user']['name']) ?> · browsing all public listings.<?php else: ?>Browsing as a guest · no account needed to explore listings.<?php endif ?></p><div class="chips"><a class="button" href="products.php">All products</a><?php foreach($categories as $c): ?><a class="button" href="products.php?category=<?= (int)$c['id'] ?>"><?= htmlspecialchars($c['name']) ?></a><?php endforeach ?></div><div class="grid" style="margin-top:24px"><?php foreach($products as $product): include __DIR__.'/views/product-card.php'; endforeach ?></div><?php if(!$products): ?><p class="muted">No listings matched. Try another search.</p><?php endif ?></main><nav class="mobile-nav"><a href="index.php">Explore</a><a href="sell.php">Sell</a><a href="messages.php">Messages</a><a href="<?= !empty($_SESSION['user']) ? 'profile.php?id=' . (int)$_SESSION['user']['id'] : 'register.php' ?>"><?= !empty($_SESSION['user']) ? 'Profile' : 'Join' ?></a></nav></body></html>
